"""Representative editorial review of the first 18 matrix pathways."""
NOTES={
'basis-images':('Read unit-vector coefficients.','Correct row/column confusion.','Construct matrix from basis images.','Recover basis images by linear combinations.','Recover matrix from independent observations and predict another image.','Classify dependent and independent observations; distinguish unique, impossible and arbitrary second column.'),
'collapse':('Recognise parallel vectors.','Refute zero-determinant implies zero map.','Find rank-one image line.','Find zero preimages and image of a translated line.','Recover singular entry, image and kernel.','Revised: reconstruct unique rank-one map from kernel and basis image; classify every target preimage.'),
'collapse-parameter':('Signed determinant prerequisite.','Distinguish collapse to line from zero map.','Find parameter causing zero area.','Find both collapse values and image lines.','Use discriminant to force one collapse value.','Classify counts, image and kernel for variable determinant targets.'),
'composition-compute':('Quarter-turn coordinates.','Use a counterexample to commutativity.','Multiply in application order.','Compute composition and image line.','Recover missing matrix and verify point image.','Derive necessary and sufficient target-entry conditions for either shear order, including both orders.'),
'composition-order':('Sequential arithmetic.','Test reversed order on a point.','Calculate correct composition.','Map a line and verify composition.','Infer shear parameter and predict reversed-order image.','AE revision: recover both candidate orders from first observation; reject one using a second ray observation.'),
'describe-transform':('Map basis vectors.','Distinguish reflection and rotation.','Describe quarter-turn.','Combine scaling with a reflection and find its axis.','Reconstruct reflection using fixed and reversed directions.','General scaled reflection classification and robust axis direction; enrichment only.'),
'det-area':('Rectangle area.','Distinguish signed determinant from unsigned area.','Use determinant magnitude.','Compose maps and track orientation.','Infer both parameter values and orientations.','Classify area-scale counts with absolute determinant, including zero and critical magnitude.'),
'det-classification':('Calculate signed determinant.','Refute nonzero entries imply invertibility.','Classify 2x2 and 3x3 examples.','Infer product singularity without multiplying.','Find when exactly one matrix is singular.','Classify intersection and differences of two singularity loci in parameter space.'),
'det-three':('Two-by-two determinant prerequisite.','Correct sign after swapping rows.','Cofactor expansion.','Use row replacement to simplify determinant.','Find singular parameter and certify rank two.','Factor cubic determinant and exclude rank below two at each root; rank terminology to be mapped carefully.'),
'det-two':('Evaluate arithmetic expression.','Explain row-swap sign.','Calculate signed determinant.','Recover determinant from product.','Infer both parameter values and invertibility.','Revised: combine det A and det(A+I) to recover sum/product; classify ordered diagonal entries and both invertibility conditions.'),
'figure-images':('Scale one coordinate.','Correct basis-image column confusion.','Map a point.','Map triangle and supporting line.','Invert vertex image and recover area.','Classify a moving line image as point, vertical or nonvertical; rendering needed for geometric teaching.'),
'fixed-invariant':('Test line membership.','Distinguish setwise and pointwise.','Map vertical line and classify it.','Classify three affine lines.','Infer parameter from invariant slope and find fixed points.','Retain diagonal parameter family as canonical affine invariance including identity and singular boundaries.'),
'fixed-points':('Solve elementary linear equation.','Distinguish invariant axis from fixed points.','Solve fixed-point equations.','Link displacement direction with fixed locus.','Infer parameter from prescribed fixed point then recover locus.','Classify all fixed-point sets of upper triangular family, excluding identity.'),
'identity-operations':('Multiplicative identity prerequisite.','Distinguish adding from multiplying identity.','Simplify linear matrix expression.','Find compatible rectangular identity sizes.','Recover inverse entry and verify both products.','Classify self-inverse matrices using product identities and prove invertibility.'),
'inconsistent-geometry':('Parallel disjoint planes.','Refute pairwise intersection implies common point.','Eliminate to obtain contradiction.','Find three pairwise intersection lines.','Infer consistency parameter and prove pairwise intersections still exist otherwise.','Classify common and pairwise intersections, including a disjoint parallel pair and three distinct parallel lines.'),
'invariant-lines':('Find direction vector.','Distinguish setwise and pointwise invariance.','Classify invariant lines through origin.','Map translated line and compare.','Find all invariant lines of triangular map including vertical case.','Revised: classify affine lines under shear and reconstruct line of prescribed pointwise displacement.'),
'inverse-identities':('Multiplicative reciprocal.','Correct inverse product equals zero.','Simplify inverse identities without computing inverse.','Simplify nested products before computation.','Recover unknown matrix from inverse equation.','Classify when A+A inverse is scalar identity; handle all parameter branches.'),
'inverse-product':('Undo successive multipliers.','Explain reversed inverse order.','Apply inverse-product rule.','Recover intermediate and initial points.','Recover unknown factor and verify original equation.','Classify when inverses exist and when incorrect order nevertheless agrees.'),
}
def scope(path,tier):
    if path not in NOTES or tier not in range(1,7): raise ValueError('Not reviewed in FM-16AI')
    if path=='describe-transform' and tier==6:return 'enrichment_only'
    return {1:'prerequisite_bridge_reviewed',2:'conceptual_diagnostic_reviewed',3:'syllabus_linked_candidate',4:'syllabus_linked_candidate',5:'syllabus_linked_candidate',6:'challenge_candidate'}[tier]
